	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Regulator
	 */
		public Regulator createRegulator( CreateRegulatorCommand command ) {

		Regulator entity = new Regulator();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setRegulatorId( command.getRegulatorId() );
            entity.setName( command.getName() );
            entity.setJurisdiction( command.getJurisdiction() );
            entity.setAddress( command.getAddress() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Regulator {0} ", entity.toString() );

		return entity;
	}

